namespace ghidra.debug.api.listing;






using docking.widgets.fieldpanel.support;
using generic.theme;
using ghidra.app.util.viewer.listingpanel;
using ghidra.app.util.viewer.listingpanel;
using ghidra.util.ColorUtils;

public class MultiBlendedListingBackgroundColorModel : ListingBackgroundColorModel {
	private static readonly Color COLOR_BACKGROUND = new GColor("color.bg");

	private List<BackgroundColorModel> models = new();

	private ColorBlender blender = new ColorBlender();

	public MultiBlendedListingBackgroundColorModel() {
	}

	public void addModel(BackgroundColorModel m) {
		models.add(m);
	}

	public void removeModel(BackgroundColorModel m) {
		models.remove(m);
	}

	/* @Override */
	public Color getBackgroundColor(BigInteger index) {
		blender.clear();
		foreach (BackgroundColorModel m in models) {
			Color c = m.getBackgroundColor(index);
			if (c == null) {
				continue;
			}
			if (c.equals(m.getDefaultBackgroundColor())) {
				continue;
			}
			blender.add(c);
		}
		return blender.getColor(getDefaultBackgroundColor());
	}

	/* @Override */
	public Color getDefaultBackgroundColor() {
		if (models.isEmpty()) {
			return COLOR_BACKGROUND;
		}
		return models.get(0).getDefaultBackgroundColor();
	}

	/* @Override */
	public void setDefaultBackgroundColor(Color c) {
		foreach (BackgroundColorModel m in models) {
			m.setDefaultBackgroundColor(c);
		}
	}

	/* @Override */
	public void modelDataChanged(ListingPanel listingPanel) {
		foreach (BackgroundColorModel m in models) {
			if (!(m is ListingBackgroundColorModel)) {
				continue;
			}
			ListingBackgroundColorModel lm = (ListingBackgroundColorModel) m;
			lm.modelDataChanged(listingPanel);
		}
	}
}
